import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, unzipInputArray } from './test-utils'

describe('Flow Trigger Instance Plugin Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // -----------------------------------------------------------------------------
    // Flow Trigger Instance Plugin Tests
    // Tests for handling empty trigger inputs
    // -----------------------------------------------------------------------------
    describe('Empty Inputs in the Trigger instance', () => {
        test('Knowledge Management trigger with no inputs returns empty array', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'flow-def-knowledge-management-trigger.now.ts')

            // Verify trigger instance was created
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]
            expect(triggerInstance).toBeDefined()
            expect(triggerInstance.trigger_inputs).toBeDefined()

            // Decode and verify empty inputs array
            const triggerInputs = unzipInputArray(triggerInstance.trigger_inputs)
            expect(Array.isArray(triggerInputs)).toBe(true)
            expect(triggerInputs).toHaveLength(0)
        })

        test('SLA Task trigger with empty inputs returns empty array', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'flow-def-sla-task-trigger.now.ts')

            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]
            const triggerInputs = unzipInputArray(triggerInstance.trigger_inputs)

            expect(triggerInputs).toEqual([])
            expect(triggerInputs).toHaveLength(0)
        })
    })

    // -----------------------------------------------------------------------------
    // Reference Column Dot-Walking Tests
    // Tests that code with reference column dot-walking compiles without TypeScript errors
    // -----------------------------------------------------------------------------
    describe('Reference Column Dot-Walking in Trigger Outputs', () => {
        test('Knowledge Management trigger with dot-walking compiles and generates flow', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'flow-def-knowledge-management-trigger.now.ts')

            // Verify flow was created successfully
            expect(merged['sys_hub_flow']).toHaveLength(1)
            expect(merged['sys_hub_flow'][0].name).toBe('Knowledge Management Flow')
            expect(merged['sys_hub_flow'][0].description).toBe('Trigger with reference column dot-walking')

            // Verify action instances were created (2 log actions)
            expect(merged['sys_hub_action_instance_v2']).toHaveLength(2)

            // Verify trigger instance was created
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            // Verify dot-walked reference fields are present in action inputs as data pills
            const actionInstance1 = merged['sys_hub_action_instance_v2'][0]
            const actionInstance1Inputs = unzipInputArray(actionInstance1.values)
            const logMessage1 = findInput(actionInstance1Inputs, 'log_message')

            // Check for data pills with dot-walked knowledge reference fields
            expect(logMessage1.value).toContain('{{Knowledge Management_1.knowledge.helpful_count}}')
        })

        test('SLA Task trigger with dot-walking compiles and generates flow', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'flow-def-sla-task-trigger.now.ts')

            // Verify flow was created successfully
            expect(merged['sys_hub_flow']).toHaveLength(1)
            expect(merged['sys_hub_flow'][0].name).toBe('SLA Task Flow')
            expect(merged['sys_hub_flow'][0].description).toBe('SLA trigger with reference column dot-walking')

            // Verify action instances were created (2 log actions)
            expect(merged['sys_hub_action_instance_v2']).toHaveLength(2)

            // Verify trigger instance was created
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            // Verify dot-walked reference fields are present in action inputs as data pills
            const actionInstance1 = merged['sys_hub_action_instance_v2'][0]
            const actionInstance1Inputs = unzipInputArray(actionInstance1.values)
            const logMessage1 = findInput(actionInstance1Inputs, 'log_message')

            // Check for data pills with dot-walked task_sla_record reference fields
            expect(logMessage1.value).toContain('{{SLA Task_1.task_sla_record.sys_mod_count}}')
            expect(logMessage1.value).toContain('{{SLA Task_1.task_sla_record.active}}')
        })
    })
})
